// The parts that need a real browser: the folder walk in its worker over a real directory handle
// (the origin-private file system stands in for a picked folder), and the IndexedDB entry cache.
// The files are a few generated bytes, not music.
import { afterEach, describe, expect, it } from "vitest";
import type { DirectoryHandleLike } from "../local-files.ts";
import { indexedDbEntryCache } from "./entry-cache.ts";
import type { ScannedFile } from "./scan.ts";
import { scanAnywhere, scanInWorker } from "./scanner.ts";

const FOLDER = "music-folder-browser-test";

async function realFolder(files: Readonly<Record<string, string>>): Promise<FileSystemDirectoryHandle> {
  const root = await navigator.storage.getDirectory();
  await root.removeEntry(FOLDER, { recursive: true }).catch(() => undefined);
  const folder = await root.getDirectoryHandle(FOLDER, { create: true });
  for (const [path, text] of Object.entries(files)) {
    const parts = path.split("/");
    const name = parts.pop() ?? path;
    let parent = folder;
    for (const part of parts) parent = await parent.getDirectoryHandle(part, { create: true });
    const writable = await (await parent.getFileHandle(name, { create: true })).createWritable();
    await writable.write(text);
    await writable.close();
  }
  return folder;
}

describe("music folder in the browser", () => {
  afterEach(async () => {
    const root = await navigator.storage.getDirectory();
    await root.removeEntry(FOLDER, { recursive: true }).catch(() => undefined);
  });

  it("walks a real folder in a worker, handing back paths, stamps and handles that read", async () => {
    const folder = await realFolder({ "a.mp3": "aaa", "House/b.wav": "bb", "notes.txt": "x" });
    const found: ScannedFile[] = [];

    const summary = await scanInWorker(folder as unknown as DirectoryHandleLike, { onBatch: (batch) => found.push(...batch) });

    expect(summary).toEqual({ files: 2, skipped: 0, truncated: false, xml: [] });
    expect(found.map((file) => file.path).toSorted()).toEqual([`${FOLDER}/House/b.wav`, `${FOLDER}/a.mp3`]);
    const a = found.find((file) => file.name === "a.mp3");
    expect(a?.size).toBe(3);
    expect(await (await a?.handle.getFile())?.text()).toBe("aaa");
  });

  it("chooses the worker for a real handle", async () => {
    const folder = await realFolder({ "a.mp3": "a" });
    const found: ScannedFile[] = [];

    await scanAnywhere(folder as unknown as DirectoryHandleLike, { onBatch: (batch) => found.push(...batch) });

    expect(found).toHaveLength(1);
  });

  it("keeps what was analysed in IndexedDB, by path, size and date", async () => {
    const name = `learn-to-dj-library-test-${String(Date.now())}`;
    const cache = indexedDbEntryCache(name);

    await cache.put({ key: "Music/a.mp3|3|1", outcome: "analysed", contentHash: "abc", bpm: 124, durationSec: 300 });
    await cache.put({ key: "Music/b.mp3|3|1", outcome: "failed", reason: "would not decode" });
    const found = await cache.getMany(["Music/a.mp3|3|1", "Music/b.mp3|3|1", "Music/c.mp3|3|1"]);

    expect(found.get("Music/a.mp3|3|1")).toMatchObject({ outcome: "analysed", bpm: 124 });
    expect(found.get("Music/b.mp3|3|1")).toMatchObject({ outcome: "failed" });
    expect(found.has("Music/c.mp3|3|1")).toBe(false);
    expect(await indexedDbEntryCache(name).getMany(["Music/a.mp3|3|1"])).toHaveProperty("size", 1);
  });
});
